// Config: edit these values for your company; nothing else in the scenario hard-codes them.
// Schedule: set this scenario to run every Monday at 07:00; Make keeps the schedule outside the blueprint.
return {
  "stop_flag_url": "https://<your stop list API>/stop_flags/R5.4",
  "table_api_url": "https://<your table API for the key log, decision log and exception queue>",
  "workflow_owner": "<your workflow owner>",
  "crm_url": "https://<your CRM API>",
  "messaging_url": "https://<your messaging API>",
  "salesperson_limit": "<your salesperson's limit, after discount>",
  "sales_lead_limit": "<your sales lead's limit, after discount>",
  "standard_discount_pct": "<your standard line discount, %>",
  "approvers": {
    "salesperson": {
      "deputy": "<your salespeople's deputy>",
      "deadline_hours": "<hours>"
    },
    "sales_lead": {
      "person": "<your sales lead>",
      "deputy": "<deputy>",
      "deadline_hours": "<hours>"
    },
    "ceo": {
      "person": "<your owner or CEO>",
      "deputy": "<deputy>",
      "deadline_hours": "<hours>"
    }
  },
  "checklist": "<link to your copy of Book 1's Checklist 13.1, the quote approver's check>",
  "systems_owner": "<your systems owner>"
};

// Adapter: the rule below is the same JavaScript as the recipe's n8n build.
// $('Step name') answers from this step's inputs: each is that step's output in this scenario.
const SOURCES = {"Config": "in0_Config", "Read quotes sent": "in1_Readquotessent"};
const LISTS = [];
const EXECUTED = [];
const DATA = {};
for (const [node, key] of Object.entries(SOURCES)) {
  const raw = input[key];
  let v = raw;
  if (typeof raw === 'string') { try { v = JSON.parse(raw); } catch (e) { v = raw; } }
  DATA[node] = LISTS.includes(node) ? (v || []).map(i => (i && i.json !== undefined ? i : { json: i })) : [{ json: v }];
}
const $ = (node) => {
  const ran = node in DATA || EXECUTED.includes(node);
  const list = () => { if (!(node in DATA)) throw new Error(`step ${node} has no data in this scenario`); return DATA[node]; };
  return { isExecuted: ran, first: () => list()[0], last: () => list()[list().length - 1], all: () => list(),
           get item() { return list()[0]; } };
};
const INPUT = "Read quotes sent";
const $input = { all: () => $(INPUT).all(), first: () => $(INPUT).first(), last: () => $(INPUT).last(), get item() { return $(INPUT).first(); } };
const $execution = { id: input.run_id };
const BODIES = (out) => ({"exception_body": JSON.stringify({ recipe: 'R5.4', item: String(out.quote_id), reason: 'quote sent unapproved', detail: 'Quote ' + out.quote_id + ' revision ' + out.revision + ' was sent without approval of that revision', owner: $('Config').first().json.approvers.sales_lead.person }), "ben_message": JSON.stringify({ to: $('Config').first().json.approvers.sales_lead.person, subject: 'Quote sent without approval', text: 'Quote ' + out.quote_id + ' was sent unapproved; call the customer.' })});
const one = (r) => (Array.isArray(r) ? r : [r]).filter(Boolean).map(i => (i.json !== undefined ? i.json : i));
const $json = INPUT && INPUT in DATA ? $input.first().json : {};
const __rule = () => {
// Backstop: any quote sent in the last week without approval of the revision sent.
const cfg = $('Config').first().json;
const since = Date.now() - 7 * 86400000;
const sent = $('Read quotes sent').first().json.items || [];
return sent.filter(q => (!q.sent_at || new Date(q.sent_at).getTime() >= since) && Number(q.approved_revision) !== Number(q.revision))
  .map(q => ({ json: { quote_id: q.id, revision: q.revision, salesperson: q.salesperson } }));
};
return { items: one(__rule()).map(o => Object.assign({}, o, BODIES(o))) };
